// RT11F attack table: each case gives delivered tree, current tree, target, the cell's earlier actions, and the expected outcome.
// Outcome: 'allow' (invariant holds), 'remap:M' (invariant fails, shift remap to M), 'refuse'.
export const attacks = [];
function probe(id, name, before, after, n, expected, { acted = [], writes = [] } = {}) {
  attacks.push({ id, name, before, after, n, expected, acted, writes });
}

// ---------- identity: described rows (RT11E BLOCKING 1) ----------
for (const shape of ['cell Description: Name, Value: ', 'text Value: ', 'link Description: Name, Value: ', 'menu item Description: Name, Value: ', 'image Description: Name, Value: ', 'tab Description: Name, Value: ', 'container Description: Name, Value: ', 'text field (settable) Description: Name, Value: ', 'text entry area (settable) Description: Name, Value: ', 'pop up button Description: Name, Value: ']) {
  const role = shape.split(/ \(|Description| Value/)[0].trim();
  const rows3 = names => ['standard window W', '\toutline', ...names.flatMap(x => ['\t\trow', '\t\t\t' + shape + x, '\t\t\tbutton Trash'])];
  probe('I1-' + role.replace(/ /g, ''), `${role} rows, b inserted first, click(7)`, rows3(['a.txt', 'c.txt']), rows3(['b.txt', 'a.txt', 'c.txt']), 7, role === 'menu item' ? 'refuse' : 'remap:10');
  probe('I2-' + role.replace(/ /g, ''), `${role} rows, a replaced by b, click(4)`, rows3(['a.txt', 'c.txt']), rows3(['b.txt', 'c.txt']), 4, 'refuse');
  probe('I3-' + role.replace(/ /g, ''), `${role} rows, a replaced by b, click(7) on c's Trash`, rows3(['a.txt', 'c.txt']), rows3(['b.txt', 'c.txt']), 7, 'refuse');
}
probe('I4', 'button Value: Save to Delete above target', ['standard window W', '\tbutton Value: Save', '\tbutton OK'], ['standard window W', '\tbutton Value: Delete', '\tbutton OK'], 2, 'refuse');
probe('I5', 'button Value: Save to Delete as target', ['standard window W', '\tbutton Value: Save'], ['standard window W', '\tbutton Value: Delete'], 1, 'refuse');
probe('I6', 'cell ID: nameCol Value swap, click(4)', ['standard window W', '\ttable', '\t\trow', '\t\t\tcell ID: nameCol, Value: a', '\t\t\tbutton Trash', '\t\trow', '\t\t\tcell ID: nameCol, Value: c', '\t\t\tbutton Trash'],
  ['standard window W', '\ttable', '\t\trow', '\t\t\tcell ID: nameCol, Value: b', '\t\t\tbutton Trash', '\t\trow', '\t\t\tcell ID: nameCol, Value: c', '\t\t\tbutton Trash'], 4, 'refuse');

// ---------- state drift above a commit control (RT11E SHOULD-FIX 1 and 2) ----------
const pay = (amount, extra = []) => ['standard window W', '\ttext field (settable) Description: Amount, Value: ' + amount, '\tcombo box (settable) Description: Recipient, Value: Alice', '\tpop up button Plan, Value: Basic $5', '\tcheckbox Description: Add insurance, Value: 0', ...extra, '\tbutton Confirm'];
probe('S1', 'Amount 5 to 500 above Confirm, cell never touched it', pay('5'), pay('500'), 5, 'refuse');
probe('S2', 'Amount 5 to 500 above Confirm, cell wrote 500 itself', pay('5'), pay('500'), 5, 'allow', { acted: [1], writes: [[1, '500']] });
probe('S3', 'Amount 5 to 500 above Pay (payment target), cell wrote it', pay('5').map(l => l.replace('Confirm', 'Pay')), pay('500').map(l => l.replace('Confirm', 'Pay')), 5, 'refuse', { acted: [1], writes: [[1, '500']] });
probe('S4', 'Recipient Alice to Bob above Send, untouched', pay('5').map(l => l.replace('Confirm', 'Send')), pay('5').map(l => l.replace('Confirm', 'Send').replace('Value: Alice', 'Value: Bob')), 5, 'refuse');
probe('S5', 'Pop up Basic $5 to Pro $500 above Continue, untouched', pay('5').map(l => l.replace('Confirm', 'Continue')), pay('5').map(l => l.replace('Confirm', 'Continue').replace('Basic $5', 'Pro $500')), 5, 'refuse');
probe('S6', 'Pop up Basic to Pro after the cell clicked the pop up (its menu option was a separate line, now gone)', pay('5', ['\tmenu', '\t\tmenu item Pro $500']), pay('5').map(l => l.replace('Basic $5', 'Pro $500')), 7, 'remap:5', { acted: [3, 6] });
probe('S7', 'Checkbox Add insurance 0 to 1 above Go, untouched', pay('5').map(l => l.replace('Confirm', 'Go')), pay('5').map(l => l.replace('Confirm', 'Go').replace('insurance, Value: 0', 'insurance, Value: 1')), 5, 'refuse');
probe('S8', 'Checkbox 0 to 1 above Go, cell clicked the checkbox', pay('5').map(l => l.replace('Confirm', 'Go')), pay('5').map(l => l.replace('Confirm', 'Go').replace('insurance, Value: 0', 'insurance, Value: 1')), 5, 'allow', { acted: [4] });
probe('S9', 'Total text $5 to $500 above Place order', ['standard window W', '\ttext Description: Total, Value: $5', '\tbutton Place order'], ['standard window W', '\ttext Description: Total, Value: $500', '\tbutton Place order'], 2, 'refuse');
probe('S10', 'Total text $5 to $500 above a neutral Next (text Value is identity)', ['standard window W', '\ttext Description: Total, Value: $5', '\tbutton Next'], ['standard window W', '\ttext Description: Total, Value: $500', '\tbutton Next'], 2, 'refuse');

